def transform(grid):
    out = [row[:] for row in grid]
    marker_row = next(i for i, row in enumerate(grid) if any(v in (2, 8) for v in row))
    for col, value in enumerate(grid[marker_row]):
        if value in (2, 8):
            above = 4 if value == 2 else 3
            for distance in range(1, above + 1):
                r = marker_row - distance
                if r >= 0:
                    out[r][col] = value if distance == above else 1
    return out
